<?php

namespace App\Data\Automations;

use Spatie\LaravelData\Attributes\PropertyForMorph;
use Spatie\LaravelData\Contracts\PropertyMorphableData;
use Spatie\LaravelData\Data;

/**
 * One step of an automation. `type` picks the subclass; `id` is generated by the client so
 * errors and run logs can point at the step.
 */
abstract class StepData extends Data implements PropertyMorphableData
{
    public string $id;

    #[PropertyForMorph]
    public string $type;

    public static function morph(array $properties): ?string
    {
        return match ($properties['type'] ?? null) {
            'condition' => ConditionStepData::class,
            'action' => ActionStepData::class,
            'delay' => DelayStepData::class,
            'paths' => PathsStepData::class,
            'stop' => StopStepData::class,
            default => null,
        };
    }
}
